/// Metni seçer ve {n}, {m} gibi yer tutucuları doldurur.
String pt(String lang, String key, [Map<String, Object> params = const {}]) {
  final row = kPartiTexts[key];
  var s = row == null ? key : Strings.pick(row, lang);
  params.forEach((k, v) => s = s.replaceAll('{$k}', '$v'));
  return s;
}
